export default async function install(app){const host=document.getElementById('app-widget-host-place-search');app.assert(host?.shadowRoot,'Search wrapper is missing');app.assert('closeOnEscDisabled' in host,'Search wrapper Escape setting is unavailable');const previous={expanded:host.expanded,autoCollapse:host.autoCollapse,closeOnEscDisabled:host.closeOnEscDisabled};const style=document.createElement('style');style.textContent='.toggle {visibility:hidden!important;pointer-events:none!important;}';host.shadowRoot.append(style);const keepOpen=()=>{if(!host.closeOnEscDisabled)host.closeOnEscDisabled=true;if(host.autoCollapse)host.autoCollapse=false;if(!host.expanded)host.expanded=true;};const observer=new MutationObserver(keepOpen);app.onCleanup(()=>{observer.disconnect();style.remove();host.expanded=previous.expanded;host.autoCollapse=previous.autoCollapse;host.closeOnEscDisabled=previous.closeOnEscDisabled;});observer.observe(host,{attributes:true,attributeFilter:['expanded','auto-collapse','close-on-esc-disabled']});keepOpen();const inspect=()=>{const search=document.getElementById('app-widget-place-search'),rect=search?.getBoundingClientRect();return {expanded:host.expanded,autoCollapse:host.autoCollapse,closeOnEscDisabled:host.closeOnEscDisabled,toggleVisibility:getComputedStyle(host.shadowRoot.querySelector('.toggle')).visibility,searchRect:rect?{x:rect.x,y:rect.y,width:rect.width,height:rect.height}:null};};app.actions.register('inspect-search-open-state',inspect);await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return inspect();}